        return 1
    return n * factorial(n - 1)

print(factorial(6))  # 720

def promedio(*numeros: float) -> float:
    if not numeros:
        return 0.0
    return sum(numeros) / len(numeros)

print(promedio(1, 2, 3, 4, 5))  # 3.0

def maximo(a, b, c):
    """Retorna el mayor de tres valores."""
    return max(a, b, c)

print(maximo(3, 7, 5))   # 7

def es_primo(n: int) -> bool:
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

primos = [n for n in range(2, 30) if es_primo(n)]
print(primos)

def contar_vocales(texto: str) -> int:
    return sum(1 for c in texto.lower() if c in "aeiou")

print(contar_vocales("Hola Mundo"))  # 4

def invertir_string(s: str) -> str:
    return s[::-1]

print(invertir_string("python"))  # nohtyp

